const icons={discover:'<circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/>',saved:'<path d="M6 3h12v18l-6-4-6 4z"/>',intro:'<rect x="3" y="5" width="18" height="14" rx="3"/><path d="m3 7 9 6 9-6"/>',plan:'<path d="m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3z"/>',profile:'<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>'};
const icon=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.discover}</svg>`;
const talents=[
{id:1,name:'Sarah Lim',role:'Marketing Executive',category:'Marketing',years:4,initials:'SL',color:'#e6ecfa',ink:'#586daf',skills:['Campaign strategy','CRM','Content marketing'],note:'Connects campaign planning with hands-on execution. Experienced with growing consumer brands.',achievement:'Coordinated a product launch across email, social and retail teams, delivering 1,200 event registrations.',salary:'S$4,000–5,000',availability:'Within 1 month'},
{id:2,name:'Marcus Tan',role:'Business Development Manager',category:'Business development',years:6,initials:'MT',color:'#e5ede5',ink:'#5e7861',skills:['Partnerships','B2B growth','Negotiation'],note:'Builds lasting SME partnerships. Looking to help a growing business open new markets.',achievement:'Built a partner channel from the ground up and onboarded 12 active business partners.',salary:'S$5,500–7,000',availability:'Within 1 month'},
{id:3,name:'Priya Kumar',role:'HR Executive',category:'HR',years:3,initials:'PK',color:'#f5e9de',ink:'#9b7959',skills:['Onboarding','HR operations','Employee experience'],note:'Brings structure to people operations. Comfortable supporting small, fast-growing teams.',achievement:'Created an onboarding checklist and coordinated the first month for 30 new colleagues.',salary:'S$3,500–4,500',availability:'Immediately'},
{id:4,name:'Daniel Wong',role:'Account Executive',category:'Sales',years:5,initials:'DW',color:'#e1edf2',ink:'#527a8d',skills:['Consultative sales','Account management','SaaS'],note:'Combines new-business sales with account care. Interested in consultative B2B roles.',achievement:'Achieved 120% of quarterly sales target while managing a portfolio of 35 SME customers.',salary:'S$4,500–6,000',availability:'Within 1 month'},
{id:5,name:'Aisha Rahman',role:'Office Administrator',category:'Administration',years:4,initials:'AR',color:'#efe6f1',ink:'#946e9c',skills:['Office operations','Vendor coordination','Scheduling'],note:'Keeps busy offices running smoothly. Experienced in vendor and calendar coordination.',achievement:'Coordinated an office move for 45 employees and maintained day-to-day operations throughout.',salary:'S$3,000–4,000',availability:'Immediately'},
{id:6,name:'Ethan Lee',role:'Operations & Admin Executive',category:'Administration',years:2,initials:'EL',color:'#f1ecd9',ink:'#988451',skills:['Process improvement','Excel','Event coordination'],note:'Detail-oriented support for growing teams, with practical spreadsheet and process skills.',achievement:'Reorganised purchasing records into a shared tracker used by three departments.',salary:'S$2,800–3,500',availability:'Within 1 month'}];
let state={view:'discover',mode:'employer',search:'',category:'All functions',available:'Any availability',saved:new Set(),requests:[],plan:'Free',profile:{name:'Sarah Lim',role:'Marketing Executive',salary:'S$4,000–5,000',availability:'Within 1 month',interest:'Campaign marketing roles in growing consumer businesses',visibility:'Discoverable'}};
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function toast(msg){let t=document.querySelector('#toast');t.textContent=msg;t.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.style.display='none',3500)}
function navigate(v){state.view=v;render()}
function setMode(m){state.mode=m;state.view=m==='employer'?'discover':'overview';render()}
function filtered(){return talents.filter(t=>(state.view!=='saved'||state.saved.has(t.id))&&(state.category==='All functions'||t.category===state.category)&&(state.available==='Any availability'||t.availability===state.available)&&`${t.name} ${t.role} ${t.skills.join(' ')}`.toLowerCase().includes(state.search.toLowerCase()))}
function render(){const emp=state.mode==='employer';const nav=emp?[['discover','Discover talent','discover'],['saved','Saved talent','saved'],['intro','Introductions','intro'],['plan','Membership','plan']]:[['overview','Overview','discover'],['profile','My Profile','profile'],['preferences','My Preferences','plan'],['opportunities','My Stars','saved'],['interest','Employer Interest','intro'],['privacy','Privacy','profile']];document.querySelector('#app').innerHTML=`<aside><div class="brand"><span class="star">✦</span><span>stars<br>collective<span style="color:#729059">.</span></span></div><div class="label">${emp?'YOUR WORKSPACE':'YOUR NEXT CHAPTER'}</div><nav>${nav.map(([v,l,i])=>`<button class="nav ${state.view===v?'active':''}" onclick="navigate('${v}')">${icon(i)}${l}${v==='saved'?`<span class="count">${state.saved.size}</span>`:''}${v==='intro'&&state.requests.length?`<span class="count">${state.requests.length}</span>`:''}</button>`).join('')}</nav><div class="aside-bottom"><div class="plan-note"><strong>${emp?state.plan+' membership':'Your talent profile'}</strong><p>${emp?'A more personal way to find your next great hire.':'Good work deserves to be discovered.'}</p><button class="text-btn" onclick="navigate('${emp?'plan':'profile'}')">${emp?'Explore membership':'Manage my profile'} ↗</button></div><div class="company"><div class="avatar">${emp?'N':'SL'}</div><div><strong>${emp?'Northstar Studio':esc(state.profile.name)}</strong><small>${emp?'Employer workspace':'Talent workspace'}</small></div></div></div></aside><main><header><span>Workspace <span style="margin:0 9px;color:#bac3ce">/</span> ${nav.find(x=>x[0]===state.view)?.[1]||'Discover talent'}</span><div class="switch" aria-label="Prototype perspective"><button class="${emp?'selected':''}" onclick="setMode('employer')">Employer view</button><button class="${!emp?'selected':''}" onclick="setMode('talent')">Talent view</button></div></header><div class="content">${body()}</div></main>`;if(['discover','saved'].includes(state.view))renderCards()}
function body(){if(['discover','saved'].includes(state.view)){let saved=state.view==='saved';return `<div class="heading"><div><div class="eyebrow">${saved?'YOUR TALENT COLLECTION':'PEOPLE, NOT JUST PROFILES'}</div><h1>${saved?'Keep great people close.':'Your next great hire starts here.'}</h1><p class="sub">${saved?'A thoughtful shortlist for your next opportunity.':'Discover professionals ready for their next chapter.'}</p></div><span class="badge">✦ Curated connections</span></div>${saved?'':`<section class="spotlight"><div><div class="eyebrow">THE COLLECTIVE EDIT / 01</div><h2>Small teams. Remarkable people.</h2><p>Meet professionals who bring initiative, versatility and hands-on experience to growing businesses.</p></div><button class="btn lime" onclick="showBrief()">Tailor my selection ↗</button></section>`}<div class="filters"><div class="search">${icon('discover')}<input aria-label="Search talent" placeholder="Search roles, skills or names" value="${esc(state.search)}" oninput="state.search=this.value;renderCards()"></div><select aria-label="Job function" onchange="state.category=this.value;renderCards()">${['All functions','Marketing','Business development','Sales','HR','Administration'].map(v=>`<option ${state.category===v?'selected':''}>${v}</option>`).join('')}</select><select aria-label="Availability" onchange="state.available=this.value;renderCards()">${['Any availability','Immediately','Within 1 month'].map(v=>`<option ${state.available===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="section-head"><h2>${saved?'Saved professionals':'Meet the collective'} <span id="resultCount"></span></h2><span>Singapore · Sample profiles</span></div><div class="grid" id="cards"></div><p class="footnote">Interactive prototype · Fictional people and companies · Changes reset when you refresh</p>`}
if(state.view==='intro')return heading('MEANINGFUL CONNECTIONS','Introductions','Every conversation starts with mutual interest.')+`<div class="callout">Try the full journey: request an introduction from a profile, then switch to Talent view to respond.</div>${state.requests.length?state.requests.map(r=>requestCard(r,false)).join(''):'<div class="panel empty"><h2>Your first conversation is ahead.</h2><p>Discover someone you would like to meet and send a thoughtful introduction.</p><button class="btn primary" style="margin-top:20px" onclick="navigate(\'discover\')">Discover talent</button></div>'}`;
if(state.view==='plan')return heading('A MEMBERSHIP THAT GROWS WITH YOU','Find your people. Build your team.','Explore subscription features. Pricing below is illustrative.')+`<div class="grid">${[['Free','S$0','Explore the collective',['Browse professional profiles','Save a personal shortlist','3 introductions per month']],['Collective','S$149','For teams hiring regularly',['Everything in Free','30 introductions per month','Tailored talent selections','Availability alerts']],['Team','S$299','Make hiring a shared effort',['Everything in Collective','100 introductions per month','Shared shortlists and team notes','Outreach and pipeline insights']]].map(([p,price,desc,features])=>`<section class="card plan ${p==='Collective'?'featured':''}"><span class="eyebrow">${p==='Collective'?'FOR GROWING TEAMS':p==='Team'?'HIRE TOGETHER':'START EXPLORING'}</span><h2>${p}</h2><div class="price">${price}<small> / month</small></div><p class="sub">${desc}</p><ul>${features.map(f=>`<li>${f}</li>`).join('')}</ul><button class="btn ${p==='Collective'?'primary':''}" onclick="selectPlan('${p}')">${state.plan===p?'Current demo plan':'Preview '+p}</button></section>`).join('')}</div><p class="footnote">Plan selection is a demo. No payment is collected. Premium features are illustrative.</p>`;
if(state.view==='profile')return profilePage();
return heading('YOUR NEXT CHAPTER','Good opportunities start with you.','Review the role, see the details and choose who you want to meet.')+`<div class="callout">Talent demo: you can review introductions sent to any sample professional.</div>${state.requests.length?state.requests.map(r=>requestCard(r,true)).join(''):`<div class="panel"><div class="eyebrow">A PROFILE THAT WORKS FOR YOU</div><h2>You’re ready to be discovered.</h2><p class="sub">No invitations yet. Switch to Employer view, open a talent profile and request an introduction to try the complete journey.</p><div class="actions"><button class="btn primary" onclick="setMode('employer')">Explore employer view</button><button class="btn" onclick="navigate('profile')">Edit my profile</button></div></div>`}`}
function heading(e,h,s){return `<div class="heading"><div><div class="eyebrow">${e}</div><h1>${h}</h1><p class="sub">${s}</p></div></div>`}
function renderCards(){const list=filtered();document.querySelector('#resultCount').textContent=`(${list.length})`;document.querySelector('#cards').innerHTML=list.length?list.map(t=>`<article class="card"><div class="card-top"><div class="avatar" style="background:${t.color};color:${t.ink}">${t.initials}</div><div><h3>${t.name}</h3><p class="role">${t.role}</p></div><button class="save ${state.saved.has(t.id)?'saved':''}" aria-label="${state.saved.has(t.id)?'Unsave':'Save'} ${t.name}" aria-pressed="${state.saved.has(t.id)}" onclick="toggleSave(${t.id})">${icon('saved')}</button></div><p class="meta">Singapore <span style="margin:0 6px">·</span> ${t.years} years of experience</p><div class="tags">${t.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><div class="fit"><strong>WHAT THEY BRING</strong>${t.note}</div><div class="card-bottom"><span class="available">${t.availability==='Immediately'?'Available now':'Open to opportunities'}</span><button class="btn" onclick="showProfile(${t.id})">Meet ${t.name.split(' ')[0]} ↗</button></div></article>`).join(''):`<div class="panel empty"><h2>${state.view==='saved'?'No saved matches yet.':'No matching professionals.'}</h2><p>${state.view==='saved'?'Save someone from Discover talent to build your shortlist.':'Try another role, skill or availability.'}</p><button class="btn" style="margin-top:20px" onclick="state.search='';state.category='All functions';state.available='Any availability';navigate('discover')">Explore all talent</button></div>`}
function toggleSave(id){state.saved.has(id)?state.saved.delete(id):state.saved.add(id);render()}
function modal(html){const d=document.querySelector('#modal');d.innerHTML=`<button class="close" aria-label="Close dialog" onclick="document.querySelector('#modal').close()">×</button>${html}`;if(!d.open)d.showModal()}
function showProfile(id){const t=talents.find(t=>t.id===id);modal(`<div class="eyebrow">MEET THE COLLECTIVE</div><h2>${t.name}</h2><p class="sub">${t.role} · Singapore · ${t.years} years’ experience</p><div class="tags">${t.skills.map(s=>`<span class="tag">${s}</span>`).join('')}</div><div class="fit"><strong>PROFESSIONAL SNAPSHOT</strong>${t.note}</div><h3 style="font-size:16px">A contribution worth knowing</h3><p class="sub">${t.achievement}</p><p style="font-size:12px;color:#7e8b9b">Sample achievement · Self-reported</p><div class="callout">${t.salary} / month<br>Available: ${t.availability}<br>Interested in: Full-time · Hybrid or on-site</div><p class="sub">Contact details are shared only after a mutual introduction.</p><button class="btn primary" onclick="introForm(${id})">Request an introduction</button>`)}
function introForm(id){if(state.requests.some(r=>r.talentId===id)){toast('You already have an introduction with this professional.');return}modal(`<h2>Make the first move.</h2><p class="sub">Introduce your opportunity to ${talents.find(t=>t.id===id).name}. Give them the details they need to decide.</p><form onsubmit="sendIntro(event,${id})"><div class="form-grid"><label class="full">Role title<input name="role" placeholder="e.g. Marketing Executive" required maxlength="100"></label><label class="full">Monthly salary range<input name="salary" placeholder="e.g. S$4,000–5,000" required maxlength="100"></label><label class="full">Why would you like to meet?<textarea name="message" required maxlength="1000" placeholder="Share a little about the role and why their experience caught your eye."></textarea></label></div><div class="actions"><button class="btn primary" type="submit">Send demo introduction</button></div><p class="sub" style="font-size:12px">Simulation only. No message is sent to a real person.</p></form>`)}
function sendIntro(e,id){e.preventDefault();const f=new FormData(e.target);state.requests.push({id:Date.now(),talentId:id,role:f.get('role').trim(),salary:f.get('salary').trim(),message:f.get('message').trim(),status:'Awaiting response'});document.querySelector('#modal').close();navigate('intro');toast('Introduction created. Switch to Talent view to respond.')}
function requestCard(r,talent){let t=talents.find(t=>t.id===r.talentId);return `<article class="request"><div class="section-head" style="margin:0 0 12px"><h3>${esc(r.role)}</h3><span class="status">${r.status}</span></div><p><strong>${talent?'Northstar Studio → '+t.name:t.name+' · '+t.role}</strong></p><p>${esc(r.salary)} / month · Singapore</p><p style="margin-top:12px">${esc(r.message)}</p>${talent&&r.status==='Awaiting response'?`<div class="actions"><button class="btn primary" onclick="respond(${r.id},'Accepted')">Accept introduction</button><button class="btn" onclick="respond(${r.id},'Declined')">Decline</button></div>`:''}${r.status==='Accepted'?'<div class="callout">You’re connected. In the full platform, both parties can now exchange contact details and arrange a conversation.</div>':''}</article>`}
function respond(id,status){state.requests.find(r=>r.id===id).status=status;render();toast(status==='Accepted'?'Introduction accepted. Your employer view is updated.':'Introduction declined. Your employer view is updated.')}
function saveProfile(e){e.preventDefault();state.profile=Object.fromEntries(new FormData(e.target));render();toast('Profile saved for this demo session.')}
function selectPlan(p){state.plan=p;render();toast(p+' selected for the demo. No payment collected.')}
function showBrief(){modal(`<h2>Who would you like to meet?</h2><p class="sub">Tailor this sample selection to your next hiring need.</p><form onsubmit="applyBrief(event)"><div class="form-grid"><label class="full">Job function<select name="category">${['Marketing','Business development','Sales','HR','Administration'].map(v=>`<option>${v}</option>`).join('')}</select></label><label class="full">When should they be available?<select name="available"><option>Any availability</option><option>Immediately</option><option>Within 1 month</option></select></label></div><div class="actions"><button type="submit" class="btn primary">Show my selection</button></div></form>`)}
function applyBrief(e){e.preventDefault();let f=new FormData(e.target);state.category=f.get('category');state.available=f.get('available');state.search='';document.querySelector('#modal').close();navigate('discover')}
if(location.hash==='#profile'){state.mode='talent';state.view='profile';}
render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'filter_talent',description:'Filter the sample talent discovery view by professional function.',inputSchema:{type:'object',properties:{category:{type:'string',enum:['All functions','Marketing','Business development','Sales','HR','Administration']}},required:['category'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['All functions','Marketing','Business development','Sales','HR','Administration'].includes(input.category))throw new Error('Unknown job function');state.category=input.category;state.search='';state.available='Any availability';state.mode='employer';navigate('discover');return {count:filtered().length,category:state.category}}})).catch(()=>{})}catch{}}
